import{_ as a,o as t,c as o,ag as d}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Panel /nay","description":"","frontmatter":{},"headers":[],"relativePath":"es/nay-lib/panel.md","filePath":"es/nay-lib/panel.md"}'),s={name:"es/nay-lib/panel.md"};function n(r,e,i,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="panel-nay" tabindex="-1">Panel /nay <a class="header-anchor" href="#panel-nay" aria-label="Permalink to &quot;Panel /nay&quot;">​</a></h1><p>Escribe <code>/nay</code> en el juego para abrir el panel de ajustes. Verás todos los scripts Nayretis que tienes permiso para configurar. Los jugadores con <code>nay.admin</code> también ven la sección <strong>Servidor</strong>: la página Nayretis, Permisos, API, Webhooks y Registro.</p><p>Los ajustes se guardan en la base de datos. Cuando pulsas <strong>Guardar</strong>, el nuevo valor se comprueba, se guarda, se anota en el <a href="/es/nay-lib/audit">registro de auditoría</a> y se aplica al instante a todos los jugadores conectados. Sin reiniciar.</p><p>Algunas páginas de scripts también tienen botones de acción, como <strong>Gestionar túneles</strong> en la página Car Wash.</p><h2 id="ajustes-de-nayretis" tabindex="-1">Ajustes de Nayretis <a class="header-anchor" href="#ajustes-de-nayretis" aria-label="Permalink to &quot;Ajustes de Nayretis&quot;">​</a></h2><p>La página <strong>Nayretis</strong> reúne los ajustes comunes a todos los scripts.</p><p>La columna <strong>En /nay</strong> es el nombre que muestra el panel. La clave es el nombre que usan <code>config.lua</code> y la <a href="/es/nay-lib/api">API HTTP</a>.</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Idioma</td><td><code>Locale</code></td><td>idioma</td><td>inglés, o el valor de <code>nay:locale</code></td><td>Idioma de todos los scripts Nayretis: inglés, francés, español, portugués, polaco o alemán.</td></tr><tr><td>Tema de la interfaz</td><td><code>Theme</code></td><td><code>graphite</code> o <code>papier</code></td><td><code>graphite</code></td><td>Aspecto de las interfaces Nayretis: oscuro (Graphite) o claro (Papier).</td></tr><tr><td>API HTTP</td><td><code>ApiEnabled</code></td><td>sí / no</td><td>no</td><td>Activa la <a href="/es/nay-lib/api">API HTTP</a>. Mientras está desactivada, todas las rutas responden <code>503 api_disabled</code>.</td></tr><tr><td>Tamaño máximo de solicitud (KB)</td><td><code>ApiMaxBodyKb</code></td><td>número, de 1 a 10240</td><td>1024</td><td>Cuerpo de solicitud más grande que acepta la API, en KB.</td></tr><tr><td>Conservación del registro (días)</td><td><code>AuditRetentionDays</code></td><td>número, de 0 a 3650</td><td>90</td><td>Las entradas del registro más antiguas se eliminan cada día. 0 lo conserva todo.</td></tr></tbody></table><h2 id="quien-puede-abrir-el-panel" tabindex="-1">Quién puede abrir el panel <a class="header-anchor" href="#quien-puede-abrir-el-panel" aria-label="Permalink to &quot;Quién puede abrir el panel&quot;">​</a></h2><ul><li><code>nay.admin</code> lo da todo.</li><li><code>nay.config</code> da los ajustes de todos los scripts.</li><li><code>nay.audit</code> abre el panel en el registro de auditoría.</li><li><code>&lt;resource&gt;.config</code> da los ajustes de un script, por ejemplo <code>nay_car_wash.config</code>.</li></ul><p>Consulta <a href="/es/nay-lib/permissions">Permisos</a> para concederlos.</p>',11)])])}const g=a(s,[["render",n]]);export{m as __pageData,g as default};
